INSERT INTO versiones_firmware (id,version,chip,tipo_dispositivo,descripcion,manifiesto,directorio,ubicacion_archivo,publicado,descontinuado,creado_por)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM versiones_firmware),'1.1.10','ESP32','riego',
'Re-provisionar un equipo ya configurado (p. ej. para cambiar de broker) ya no falla: el buffer serie se amplía a 4096 bytes y la configuración de ~550 bytes del panel llega completa aunque el loop esté en pausa o midiendo. Conserva NTP, seguridad sin conexión, cola de reportes, bloqueo de llenado y watchdog de 1.1.9.',
'{"schema_version": 1, "version": "1.1.10", "chip": "ESP32", "tipo_dispositivo": "riego", "source_sha256": "fd08cdfdb4413dcaf567310a7c0bfbdefcc7d2c01eb4555d2222df1e421d3fed", "segmentos": [{"nombre": "esp32.ino.bootloader.bin", "direccion": 4096, "tamano": 24992, "sha256": "427f96e10c620c4f062dab15da54fc45494d897e8397ae6f3aecc98c42d7e379"}, {"nombre": "esp32.ino.partitions.bin", "direccion": 32768, "tamano": 3072, "sha256": "148b959cbff1c38aa8e1d5c0ba9d612c54997b945e56a63f41223eef650653a1"}, {"nombre": "boot_app0.bin", "direccion": 57344, "tamano": 8192, "sha256": "f94c5d786a7a8fab06ac5d10e33bf37711a6697636dc037559ea19cc410a17f0"}, {"nombre": "esp32.ino.bin", "direccion": 65536, "tamano": 1051168, "sha256": "73766086e50261aa455b0c358be28ec6127d688d6c67fd5b4b841cb997a72b4d"}]}'::jsonb,'esp32-riego-1.1.10','firmware_store/esp32-riego-1.1.10',true,false,
(SELECT MIN(id) FROM usuarios WHERE id_rol=1)
WHERE EXISTS (SELECT 1 FROM usuarios WHERE id_rol=1) AND NOT EXISTS
(SELECT 1 FROM versiones_firmware WHERE version='1.1.10' AND chip='ESP32' AND tipo_dispositivo='riego');
