directorio='esp32-riego-1.1.10',ubicacion_archivo='firmware_store/esp32-riego-1.1.10',publicado=true,descontinuado=false,fecha_descontinuado=NULL
WHERE version='1.1.10' AND chip='ESP32' AND tipo_dispositivo='riego';
UPDATE versiones_firmware SET publicado=false,descontinuado=true,fecha_descontinuado=COALESCE(fecha_descontinuado,now())
WHERE chip='ESP32' AND tipo_dispositivo='riego' AND version<>'1.1.10';
SELECT setval(pg_get_serial_sequence('versiones_firmware','id'),(SELECT MAX(id) FROM versiones_firmware));
